{
  "reference_answer": "Honestly, it depends on the kind of work I'm doing. If it's something that needs deep focus, like writing a report or preparing a presentation, I'd much rather be at home, because I can shut the door and get into a rhythm without anyone tapping me on the shoulder. But for anything creative or collaborative, working from home actually slows me down. I remember trying to brainstorm ideas over a video call, and it just felt flat — nobody was building on each other's suggestions the way we would in the same room. So I wouldn't say I prefer it across the board. I'd choose it for certain tasks, not as a fixed way of working.",
  "reference_angle_summary": "独立主线：以“任务类型”为唯一判断标准，用深度专注与协作创意两种任务对比，得出有条件偏好；示例不代表用户经历。",
  "takeaway_expressions": [
    {
      "expression": "it depends on the kind of work I'm doing",
      "meaning_zh": "这取决于我在做哪种工作",
      "why_useful": "回答偏好类问题时，用条件化表达避免绝对化，自然引出对比。",
      "example": "It depends on the kind of work I'm doing — some tasks need quiet, others need people.",
      "usage_note": "后面常接 because 或具体分类，让理由落地。"
    },
    {
      "expression": "get into a rhythm",
      "meaning_zh": "进入状态、找到节奏",
      "why_useful": "描述专注或高效状态时比 be focused 更自然，适合工作学习话题。",
      "example": "Once I get into a rhythm, I can work for hours without checking my phone.",
      "usage_note": "常与 once、without interruptions 等搭配。"
    },
    {
      "expression": "I wouldn't say I prefer it across the board",
      "meaning_zh": "我不会说我在所有情况下都更喜欢它",
      "why_useful": "用于给出有保留的偏好，语气自然，避免 yes/no 的绝对回答。",
      "example": "I wouldn't say I prefer it across the board, but for long tasks it works well.",
      "usage_note": "across the board 表示“在所有方面/情况下”。"
    }
  ]
}
